    let r = batch(
        &mut h,
        "SendMessageBatch",
        "f.fifo",
        json!([
            {"Id": "1", "Body": "aa", "GroupId": "g", "DeduplicationId": "d"},
            {"Id": "2", "Body": "bb", "GroupId": "g", "DeduplicationId": "d"},
            {"Id": "3", "Body": "toolong", "GroupId": "g", "DeduplicationId": "e"},
            {"Id": "4", "Body": "cc", "GroupId": "g", "DeduplicationId": "f"},
        ]),
