}

#[test]
fn delete_batch_handles_each_handle_once() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    for body in ["a", "b"] {
        send(&mut h, "q", body);
    }
    let got = receive(&mut h, "q", 2);
    let (h1, h2) = (got[0]["ReceiptHandle"].clone(), got[1]["ReceiptHandle"].clone());
    let r = batch(
        &mut h,
        "DeleteMessageBatch",
        "q",
        json!([
            {"Id": "x", "ReceiptHandle": h1},
            {"Id": "y", "ReceiptHandle": h1},
            {"Id": "z", "ReceiptHandle": "r-999"},
            {"Id": "w"},
            {"Id": "v", "ReceiptHandle": 5},
            {"Id": "u", "ReceiptHandle": h2},
        ]),
    );
    assert_eq!(r["Successful"], json!([{"Id": "x"}, {"Id": "u"}]));
    let codes: Vec<(&str, &str)> = r["Failed"]
        .as_array()
        .unwrap()
        .iter()
        .map(|f| (f["Id"].as_str().unwrap(), f["error"]["code"].as_str().unwrap()))
        .collect();
    assert_eq!(
        codes,
        [
            ("y", "ReceiptHandleExpired"),
            ("z", "ReceiptHandleInvalid"),
            ("w", "MissingParameter"),
            ("v", "InvalidParameterValue")
        ]
    );
    let counts = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Counts"].clone();
    assert_eq!(counts, json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

#[test]
fn batch_rules_fail_the_whole_request() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    for command in ["SendMessageBatch", "DeleteMessageBatch"] {
        assert_eq!(batch_err(&mut h, command, json!([])), "EmptyBatchRequest");
        let eleven: Vec<Value> = (0..11).map(|i| json!({"Id": format!("i{i}"), "Body": "b"})).collect();
        assert_eq!(batch_err(&mut h, command, json!(eleven)), "TooManyEntriesInBatchRequest");
        // Too many wins over a bad id; bad id wins over duplicates.
        let mut bad = eleven.clone();
        bad[0] = json!(7);
        assert_eq!(batch_err(&mut h, command, json!(bad)), "TooManyEntriesInBatchRequest");
        for entries in [
            json!([7]),
            json!([null]),
            json!([{"Body": "b"}]),
            json!([{"Id": null}]),
            json!([{"Id": 1}]),
            json!([{"Id": ""}]),
            json!([{"Id": "a b"}]),
            json!([{"Id": "x".repeat(81)}]),
            json!([{"Id": "a"}, {"Id": "a"}, 5]),
        ] {
            assert_eq!(batch_err(&mut h, command, entries.clone()), "InvalidBatchEntryId", "{entries}");
        }
        let ten: Vec<Value> = (0..10).map(|i| json!({"Id": format!("i{i}"), "Body": "b", "ReceiptHandle": "r-1"})).collect();
        let r = h.ok(json!({"Command": command, "QueueName": "q", "Entries": ten}));
        assert_eq!(r["Failed"].as_array().map(Vec::len).unwrap() + r["Successful"].as_array().unwrap().len(), 10);
        let dup = json!([{"Id": "a", "Body": "b"}, {"Id": "a", "Body": "c"}]);
        assert_eq!(batch_err(&mut h, command, dup), "BatchEntryIdsNotDistinct");
        let max_id = json!([{"Id": "x".repeat(80), "Body": "b", "ReceiptHandle": "r-1"}]);
        h.ok(json!({"Command": command, "QueueName": "q", "Entries": max_id}));
        // Ids are case-sensitive.
        let cased = json!([{"Id": "a", "Body": "b"}, {"Id": "A", "Body": "b"}]);
        h.ok(json!({"Command": command, "QueueName": "q", "Entries": cased}));
    }
}

#[test]
fn batch_check_order_before_the_rules() {
    let mut h = Harness::new();
    for command in ["SendMessageBatch", "DeleteMessageBatch"] {
        let run = |h: &mut Harness, c: Value| h.err(c);
        assert_eq!(run(&mut h, json!({"Command": command, "Entries": []})), "MissingParameter");
        assert_eq!(run(&mut h, json!({"Command": command, "QueueName": "q"})), "MissingParameter");
        assert_eq!(
            run(&mut h, json!({"Command": command, "QueueName": "q", "Entries": null})),
            "MissingParameter"
        );
        assert_eq!(
            run(&mut h, json!({"Command": command, "QueueName": "q", "Entries": {}})),
            "InvalidParameterValue"
        );
        assert_eq!(
            run(&mut h, json!({"Command": command, "QueueName": 1, "Entries": []})),
            "InvalidParameterValue"
        );
        // The lookup comes before the numbered rules.
        assert_eq!(batch_err(&mut h, command, json!([])), "QueueDoesNotExist");
    }
}

